    ['inicio', 'estudar', 'escada', 'questao', 'simulado', 'progresso'].forEach(function (x) { var s = g('v-' + x); if (s) s.hidden = true; });
    EXTRAS.forEach(function (x) { x.hidden = x !== sec; });
