        '<button type="button" class="ad-fig-img' + (x.e === 'caderno' ? ' cad' : '') + '" aria-label="Ampliar: ' + e(x.t) + '"><img alt="' + e(x.t) + '" src="' + x.u + '"></button>' +
        '<p class="ad-fig-t">' + e(x.t) + '</p>';
