      if (tp && /calcular$/.test(tp.getAttribute('aria-label') || '') && !(c && /[0-9₀-₉=]/.test(c.textContent))) tp.classList.add('ad-sem-chip');
      if (!c) ps.classList.add('ad-sem-conta');
