      var rot = function (on) { bc.innerHTML = '<span>' + (on ? 'Esconder a resolução completa' : 'Ver a resolução completa') + '</span><small>' + (on ? '' : plural(np, 'passo', 'passos') + ', teoria e alternativas') + '</small>'; };
